const FormField = ({ label, id, type = "text", required, autocomplete, helperText, error, value, onChange }) => {
  return (
    <div className="form-field">
      <label htmlFor={id}>
        {label}
        {required && <span className="required-marker" aria-hidden="true">*</span>}
        {!required && <span className="helper-text" style={{ display: 'inline', marginLeft: '0.25rem' }}>(optional)</span>}
      </label>
      <input
        id={id}
        name={id}
        type={type}
        required={required}
        autoComplete={autocomplete}
        aria-describedby={`${helperText ? `${id}-helper ` : ''}${error ? `${id}-error` : ''}`.trim() || undefined}
        aria-invalid={!!error}
        value={value}
        onChange={(e) => onChange(e.target.value)}
      />
      {helperText && (
        <span id={`${id}-helper`} className="helper-text">
          {helperText}
        </span>
      )}
      {error && (
        <span id={`${id}-error`} className="error-text">
          {error}
        </span>
      )}
    </div>
  );
};

const App = () => {
  const [formData, setFormData] = useState({
    fullName: "",
    email: "",
    phone: ""
  });
  const [errors, setErrors] = useState({});
  const [submitted, setSubmitted] = useState(false);
  const mainRef = useRef(null);

  useEffect(() => {
    if (mainRef.current) {
      mainRef.current.focus();
    }
  }, [submitted]);

  const handleSubmit = (e) => {
    e.preventDefault();

    const newErrors = {};
    if (!formData.fullName.trim()) {
      newErrors.fullName = "Error: Full name is required.";
    }
    if (!formData.email.trim()) {
      newErrors.email = "Error: Email address is required.";
    } else if (!/\S+@\S+\.\S+/.test(formData.email)) {
      newErrors.email = "Error: Please enter a valid email address.";
    }

    setErrors(newErrors);

    if (Object.keys(newErrors).length === 0) {
      console.log("Form submitted successfully:", formData);
      setSubmitted(true);
    } else {
      // Focus the first invalid field
      const firstErrorField = Object.keys(newErrors)[0];
      document.getElementById(firstErrorField)?.focus();
    }
  };

  const updateField = (field, value) => {
    setFormData(prev => ({ ...prev, [field]: value }));
    // Clear error when user starts typing
    if (errors[field]) {
      setErrors(prev => {
        const next = { ...prev };
        delete next[field];
        return next;
      });
    }
  };

  if (submitted) {
    return (
      <main id="main-content" tabIndex="-1">
        <h1>Thank You</h1>
        <p>Your support request has been received. We'll get back to you soon.</p>
        <button onClick={() => {
          setSubmitted(false);
          setFormData({ fullName: "", email: "", phone: "" });
        }}>Send another message</button>
      </main>
    );
  }

  return (
    <main id="main-content" tabIndex="-1">
      <h1>Support Page</h1>
      <form onSubmit={handleSubmit} noValidate>
        <FormField
          label="Full Name"
          id="fullName"
          autocomplete="name"
          required
          error={errors.fullName}
          value={formData.fullName}
          onChange={(val) => updateField("fullName", val)}
        />
        <FormField
          label="Email Address"
          id="email"
          type="email"
          autocomplete="email"
          required
          error={errors.email}
          value={formData.email}
          onChange={(val) => updateField("email", val)}
        />
        <FormField
          label="Phone Number"
          id="phone"
          type="tel"
          autocomplete="tel"
          helperText="Expected format: (555) 555-5555"
          value={formData.phone}
          onChange={(val) => updateField("phone", val)}
        />
        <button type="submit">Submit Request</button>
      </form>
    </main>
  );
};

const root = ReactDOM.createRoot(document.getElementById('root'));
root.render(<App />);
